import json
import requests

# JSON file generated by AI model
json_file = "pothole_incident.json"

# FastAPI endpoint
api_url = "http://127.0.0.1:8000/incidents"

# Read JSON file
with open(json_file, "r") as file:
    data = json.load(file)

# Support both single incident and list of incidents
incidents = data if isinstance(data, list) else [data]

# Send incidents to FastAPI
for incident in incidents:

    try:
        response = requests.post(
            api_url,
            json=incident,
            timeout=10
        )

        print("Status Code:", response.status_code)
        print("Response:", response.text)

    except requests.exceptions.RequestException as e:
        print("API Error:", e)